import { describe, expect, test } from "bun:test";
import { readFileSync } from "fs";
import { join } from "path";
import { injectSeoAndGating, markThemeScriptsCfAsync } from "../../scripts/inject-gating";

// A real chapter page generated by mdBook v0.5.3, the version CI pins.
const fixture = readFileSync(join(import.meta.dir, "../fixtures/mdbook-0.5.3-chapter.html"), "utf-8");

const MARKED_TAG = '<script data-cfasync="false">';
const ATTRIBUTE = ' data-cfasync="false"';

// Content that identifies each of mdBook's three pre-paint theme scripts.
const THEME_SCRIPT_MARKERS = {
  defaultThemes: 'const default_light_theme = "light";',
  quoteWorkaround: "if (theme.startsWith('\"') && theme.endsWith('\"'))",
  bootstrap: 'const default_theme = window.matchMedia("(prefers-color-scheme: dark)")',
};

function countOccurrences(haystack: string, needle: string): number {
  return haystack.split(needle).length - 1;
}

function openingTagBefore(html: string, marker: string): { index: number; tag: string } {
  const markerIndex = html.indexOf(marker);
  expect(markerIndex).toBeGreaterThan(-1);
  const index = html.lastIndexOf("<script", markerIndex);
  expect(index).toBeGreaterThan(-1);
  return { index, tag: html.slice(index, html.indexOf(">", index) + 1) };
}

const injectOptions = {
  pageTitle: "Bab Pertama",
  url: "https://dawnbook.belajarcarabelajar.com/books/buku-uji-tema/content/01_bab-pertama",
  isGatedClientSide: true,
  gaId: undefined,
  bookDescription: "",
  isBookRoot: false,
};

describe("mdBook theme scripts are exempt from Rocket Loader", () => {
  test("the fixture is unmarked and holds each theme script once", () => {
    expect(countOccurrences(fixture, "data-cfasync")).toBe(0);
    for (const marker of Object.values(THEME_SCRIPT_MARKERS)) {
      expect(countOccurrences(fixture, marker)).toBe(1);
      expect(openingTagBefore(fixture, marker).tag).toBe("<script>");
    }
  });

  test("injectSeoAndGating marks each of the three theme scripts with data-cfasync=false", () => {
    const output = injectSeoAndGating(fixture, injectOptions);
    for (const marker of Object.values(THEME_SCRIPT_MARKERS)) {
      expect(openingTagBefore(output, marker).tag).toBe(MARKED_TAG);
    }
    expect(countOccurrences(output, ATTRIBUTE)).toBe(3);
    expect(output).toContain("<script>!function(){var e=window.location.pathname");
  });

  test("markThemeScriptsCfAsync changes only the three theme script opening tags", () => {
    const output = markThemeScriptsCfAsync(fixture);
    expect(countOccurrences(output, ATTRIBUTE)).toBe(countOccurrences(fixture, ATTRIBUTE) + 3);

    const tagIndexes = Object.values(THEME_SCRIPT_MARKERS)
      .map((marker) => openingTagBefore(output, marker))
      .map(({ index, tag }) => {
        expect(tag).toBe(MARKED_TAG);
        return index;
      })
      .sort((a, b) => b - a);

    let reverted = output;
    for (const index of tagIndexes) {
      const attributeStart = index + "<script".length;
      expect(reverted.slice(attributeStart, attributeStart + ATTRIBUTE.length)).toBe(ATTRIBUTE);
      reverted = reverted.slice(0, attributeStart) + reverted.slice(attributeStart + ATTRIBUTE.length);
    }
    expect(reverted).toBe(fixture);
  });

  test("markThemeScriptsCfAsync is idempotent", () => {
    const once = markThemeScriptsCfAsync(fixture);
    expect(markThemeScriptsCfAsync(once)).toBe(once);
  });

  test("throws and names the bootstrap when a themed page has no theme bootstrap script", () => {
    const broken = fixture.replace("const default_theme =", "const fallback_theme =");
    expect(broken).not.toBe(fixture);
    expect(() => markThemeScriptsCfAsync(broken)).toThrow(/theme bootstrap script/);
  });

  test("throws and names the default-themes script when a themed page has none", () => {
    const broken = fixture.replace("const default_light_theme =", "const light_theme_name =");
    expect(broken).not.toBe(fixture);
    expect(() => markThemeScriptsCfAsync(broken)).toThrow(/default-themes script/);
  });

  test("leaves a page without the mdBook theme toggle and theme scripts unchanged", () => {
    const page = `<!DOCTYPE html>
<html lang="id"><head><title>Halaman</title>
<script>window.dataLayer = window.dataLayer || [];</script>
</head><body><p>Kamu membaca halaman biasa.</p>
<script src="/app.js"></script>
</body></html>`;
    expect(markThemeScriptsCfAsync(page)).toBe(page);
  });

  test("throws and names every missing script when an mdBook page has no theme toggle id and no theme scripts", () => {
    // An mdBook upgrade could rename the toggle id and change the scripts together; the generator comment still marks the page.
    const page = `<!DOCTYPE html>
<html lang="id" class="light sidebar-visible" dir="ltr">
    <head>
        <!-- Book generated using mdBook -->
        <meta charset="UTF-8">
        <title>Bab Pertama</title>
    </head>
    <body><button id="theme-switcher" type="button"></button><p>Kamu membaca bab pertama.</p></body>
</html>`;
    expect(() => markThemeScriptsCfAsync(page)).toThrow(/default-themes script/);
    expect(() => markThemeScriptsCfAsync(page)).toThrow(/localStorage quote workaround script/);
    expect(() => markThemeScriptsCfAsync(page)).toThrow(/theme bootstrap script/);
  });

  test("throws and names only the quote workaround when a themed page lacks the localStorage quote workaround script", () => {
    const broken = fixture.replace(THEME_SCRIPT_MARKERS.quoteWorkaround, "if (theme.length > 1)");
    expect(broken).not.toBe(fixture);
    let message = "";
    try {
      markThemeScriptsCfAsync(broken);
    } catch (error) {
      message = (error as Error).message;
    }
    expect(message).toContain("localStorage quote workaround script");
    expect(message).not.toContain("default-themes script");
    expect(message).not.toContain("theme bootstrap script");
  });
});
